{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Who I Am — {{BUSINESS_NAME}}</title>
  <style>
    :root{
      --bg:#f6faf8;--card:#ffffff;--muted:#6b776f;--accent:#2b6b5a;--accent-2:#7bb59b;--glass:rgba(255,255,255,0.6);
      --maxw:920px;--radius:12px;--shadow:0 6px 20px rgba(20,30,25,0.08);
    }
    html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial; color:#23302a;background:var(--bg);-webkit-font-smoothing:antialiased}
    header{background:linear-gradient(180deg,rgba(43,107,90,0.08),transparent);padding:28px 20px}
    .nav{max-width:var(--maxw);margin:0 auto;display:flex;gap:18px;align-items:center;justify-content:space-between}
    .brand{font-weight:600;color:var(--accent);letter-spacing:0.2px}
    nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
    nav a.primary{background:var(--accent);color:#fff}
    .container{max-width:var(--maxw);margin:28px auto;padding:24px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center}
    .card{background:var(--card);border-radius:var(--radius);box-shadow:var(--shadow);padding:20px}
    h1{margin:0 0 8px;font-size:28px;color:#153426}
    p.lead{margin:0;color:var(--muted);line-height:1.5}

    /* Pattern using embedded SVG data URI (unique pattern) */
    .pattern-strip{height:120px;border-radius:10px;overflow:hidden;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='600' height='120'><defs><linearGradient id='g' x1='0' x2='1'><stop offset='0' stop-color='%232b6b5a' stop-opacity='0.08'/><stop offset='1' stop-color='%237bb59b' stop-opacity='0.02'/></linearGradient></defs><rect width='100%' height='100%' fill='url(%23g)'/><g fill='none' stroke='%232b6b5a' stroke-opacity='0.06' stroke-width='1'><path d='M0 30 q30 -10 60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0'/><path d='M0 60 q20 -8 40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0'/></g></svg>");background-size:cover}

    .split{display:grid;grid-template-columns:1fr 360px;gap:20px}
    .meta{font-size:14px;color:var(--muted)}

    /* Proof gallery */
    .proof{display:flex;flex-direction:column;gap:12px}
    .testimonial{display:flex;gap:12px;align-items:flex-start}
    .quote{flex:1}
    .quote p{margin:0;color:#173926}
    .author{font-size:13px;color:var(--muted);margin-top:8px}
    .badges{display:flex;gap:10px;align-items:center}
    .badge{background:var(--glass);padding:8px;border-radius:8px;font-size:13px;color:var(--accent);position:relative;cursor:default}
    .badge:hover{transform:translateY(-2px);transition:all .18s}
    .tooltip{position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:#fff;padding:8px;border-radius:8px;box-shadow:var(--shadow);font-size:13px;color:#223;display:none;white-space:nowrap}

    .controls{display:flex;gap:8px}
    .dot{width:10px;height:10px;border-radius:10px;background:#d6ded9;cursor:pointer}
    .dot.active{background:var(--accent)}

    footer{max-width:var(--maxw);margin:24px auto;padding:16px 24px;color:var(--muted);font-size:13px}

    @media (max-width:860px){.split{grid-template-columns:1fr}.pattern-strip{height:80px}}
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Studio</a>
        <a href="specialties.html">Offerings</a>
        <a href="about.html" class="primary">Who I Am</a>
        <a href="approach.html">How I Work</a>
        <a href="book.html">Schedule</a>
      </nav>
    </div>
  </header>

  <main class="container">
    <section class="card hero">
      <div class="split">
        <div>
          <h1>Clinical membership for steady progress</h1>
          <p class="lead">I support people making careful choices during transitions, recurring patterns, and relational challenges. Sessions are grounded in evidence-informed approaches, held with attention to safety and confidentiality. Membership options help create continuity when growth takes time.</p>
          <div style="margin-top:14px"><a href="{{PRIMARY_CTA_URL}}" class="card" style="background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none">{{PRIMARY_CTA_LABEL}}</a></div>
        </div>
        <aside>
          <div class="pattern-strip card" aria-hidden="true"></div>
          <div style="margin-top:12px;font-size:14px;color:var(--muted)">Telehealth and limited in-person options in {{CITY}}, {{STATE}} • Private, confidential notes maintained</div>
        </aside>
      </div>
    </section>

    <section class="card" style="margin-top:18px">
      <h2 style="margin:0 0 12px">Voices from practice</h2>
      <div class="proof" id="proof">
        <div class="testimonial" data-index="0">
          <div class="quote"><p>"Meeting regularly has helped me notice small patterns I used to miss. The membership model made it easier to commit to change without pressure."</p><div class="author">— A client (anonymized)</div></div>
        </div>
        <div class="testimonial" style="display:none" data-index="1">
          <div class="quote"><p>"The sessions felt steady and practical. I appreciated having time between appointments to try things out and report back."</p><div class="author">— Another client (anonymized)</div></div>
        </div>

        <div style="margin-top:12px;display:flex;align-items:center;justify-content:space-between">
          <div class="badges" id="badges">
            <div class="badge" data-tip="Board certified clinician with several years in outpatient care">Licensed Clinician
              <div class="tooltip">Licensed clinician, state board verified</div>
            </div>
            <div class="badge" data-tip="Member of local peer consultation group">Peer Consultation
              <div class="tooltip">Regular peer consultation and case review</div>
            </div>
            <div class="badge" data-tip="Focus on adult individual and relational work">Adult & Relational Practice
              <div class="tooltip">Focused services for adults and couples</div>
            </div>
          </div>
          <div class="controls" id="proof-controls" aria-hidden="false"></div>
        </div>
      </div>
    </section>

    <section class="card" style="margin-top:18px">
      <h2 style="margin:0 0 12px">Clinical note on confidentiality & scope</h2>
      <p class="meta">Sessions and records are kept private within legal and ethical limits. I do not provide emergency services. If you are in crisis or danger, please call local emergency services immediately or go to the nearest emergency department. I will provide referrals or collaborate with other providers when appropriate and with your consent.</p>
    </section>

  </main>

  <footer>
    <div style="max-width:var(--maxw);margin:0 auto;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap"> 
      <div>&copy; <span id="yr"></span> {{BUSINESS_NAME}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div style="color:var(--muted)">Licensed practice • Confidentiality respected • No crisis services</div>
    </div>
  </footer>

  <script>
    // Year
    document.getElementById('yr').textContent = new Date().getFullYear();

    // Proof gallery rotation
    (function(){
      const items = Array.from(document.querySelectorAll('.testimonial'));
      const controls = document.getElementById('proof-controls');
      let idx = 0;
      function renderControls(){
        controls.innerHTML = '';
        items.forEach((it,i)=>{
          const d = document.createElement('div');
          d.className = 'dot' + (i===idx? ' active':'');
          d.addEventListener('click',()=>{ show(i); restart(); });
          controls.appendChild(d);
        });
      }
      function show(i){ items.forEach((it,ii)=>{ it.style.display = ii===i? 'flex':'none'; }); idx=i; renderControls(); }
      function next(){ show((idx+1)%items.length); }
      let t = setInterval(next,5000);
      function restart(){ clearInterval(t); t=setInterval(next,5000); }
      renderControls();
      // badges tooltips
      document.querySelectorAll('.badge').forEach(b=>{
        const tip = b.querySelector('.tooltip');
        b.addEventListener('mouseenter',()=> tip.style.display='block');
        b.addEventListener('mouseleave',()=> tip.style.display='none');
        b.addEventListener('focus',()=> tip.style.display='block');
        b.addEventListener('blur',()=> tip.style.display='none');
      });
    })();
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfdfc;--card:#fff;--accent:#1f6653;--muted:#5c6a61;--accent-2:#8bc6a3;--radius:12px;--maxw:980px}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, Arial;color:#1f2f28;background:var(--bg)}
    header{padding:18px 20px}
    .nav{max-width:var(--maxw);margin:0 auto;display:flex;justify-content:space-between;align-items:center}
    .brand{font-weight:700;color:var(--accent)}
    nav a{margin-left:12px;text-decoration:none;color:var(--muted);padding:6px 8px;border-radius:8px}
    nav a.active{background:var(--accent);color:#fff}
    .wrap{max-width:var(--maxw);margin:26px auto;padding:0 18px}
    .intro{display:flex;gap:20px;align-items:center}
    h1{margin:0;color:#113827}
    p.lead{color:var(--muted)}
    .offer-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
    .plan{background:var(--card);border-radius:var(--radius);padding:16px;box-shadow:0 8px 18px rgba(20,30,25,0.06)}
    .price{font-size:22px;color:var(--accent);font-weight:600}
    .muted{color:var(--muted);font-size:14px}

    /* Pricing comparator */
    .toggle{display:flex;align-items:center;gap:8px;background:linear-gradient(90deg,#fff,#f7fdf6);padding:8px;border-radius:999px;width:max-content}
    .switch{width:48px;height:28px;background:#e9f3ee;border-radius:999px;position:relative;cursor:pointer}
    .knob{width:22px;height:22px;border-radius:50%;background:#fff;position:absolute;top:3px;left:3px;box-shadow:0 2px 10px rgba(20,30,25,0.12);transition:left .28s}
    .switch.active{background:var(--accent-2)}
    .switch.active .knob{left:23px}

    .price-anim{font-variant-numeric:tabular-nums}

    @media (max-width:920px){.offer-grid{grid-template-columns:1fr}.intro{flex-direction:column;align-items:flex-start}}
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Studio</a>
        <a href="specialties.html" class="active">Offerings</a>
        <a href="about.html">Who I Am</a>
        <a href="approach.html">How I Work</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="intro">
      <div>
        <h1>Ways of working</h1>
        <p class="lead">I offer recurring membership plans and short-term focused packages. Choose a rhythm that fits the concern you bring — continuity supports reflective shifts, and focused cycles can help address a tight concern.</p>
      </div>
      <div style="margin-left:auto;display:flex;align-items:center;gap:12px">
        <div style="font-size:13px;color:var(--muted)">Monthly</div>
        <div class="toggle" aria-hidden="false">
          <div id="switch" class="switch" role="switch" aria-checked="true" tabindex="0"><div class="knob"></div></div>
        </div>
        <div style="font-size:13px;color:var(--muted)">Package</div>
      </div>
    </section>

    <section class="offer-grid" id="plans">
      <div class="plan">
        <h3>Grounding Membership</h3>
        <div class="price" data-month="160" data-package="900">$<span class="price-anim" data-value>160</span><span style="font-size:13px;color:var(--muted)"> / session</span></div>
        <p class="muted">Weekly or biweekly sessions for ongoing support; priority scheduling and brief check-ins between sessions.</p>
        <ul class="muted"><li>Continuity-focused</li><li>Reduced admin friction</li><li>Private member space</li></ul>
      </div>

      <div class="plan">
        <h3>Focused Cycle</h3>
        <div class="price" data-month="180" data-package="850">$<span class="price-anim" data-value>180</span><span style="font-size:13px;color:var(--muted)"> / session</span></div>
        <p class="muted">A time-limited 8–12 session pathway for a specific concern — skill-focused and goal-oriented.</p>
        <ul class="muted"><li>Structured check-ins</li><li>Progress milestones</li><li>Clear ending plan</li></ul>
      </div>

      <div class="plan">
        <h3>Consultation Session</h3>
        <div class="price" data-month="210" data-package="600">$<span class="price-anim" data-value>210</span><span style="font-size:13px;color:var(--muted)"> / single</span></div>
        <p class="muted">Single appointments for immediate planning, intake sessions, or paperwork completion.</p>
        <ul class="muted"><li>Single-session option</li><li>Available for intake</li><li>Brief resource guidance</li></ul>
      </div>
    </section>

    <section style="margin-top:18px;background:#fff;padding:16px;border-radius:12px;box-shadow:0 8px 18px rgba(20,30,25,0.05)">
      <h3 style="margin:0 0 8px">How the comparator works</h3>
      <p class="muted">Toggle between "Monthly" and "Package" to see per-session numbers update. Package values reflect an average per-session cost when sessions are purchased as a block. Prices are illustrative and subject to assessment; exact terms are discussed at intake.</p>
      <div style="margin-top:12px"><a href="{{PRIMARY_CTA_URL}}" style="background:var(--accent);color:#fff;padding:10px 12px;border-radius:8px;text-decoration:none">Start a conversation</a></div>
    </section>

  </main>

  <script>
    // Pricing comparator behavior with animated numbers
    (function(){
      const switchEl = document.getElementById('switch');
      const plans = Array.from(document.querySelectorAll('[data-month]'));
      let monthly = true;
      function animateNumber(el, from, to, ms=400){
        const start = performance.now();
        const diff = to - from;
        function step(now){
          const p = Math.min(1,(now-start)/ms);
          const val = Math.round(from + diff * p);
          el.textContent = val;
          if(p<1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }
      function update(toMonthly){
        plans.forEach(pEl=>{
          const span = pEl.querySelector('.price-anim[data-value]');
          const from = parseInt(span.textContent,10) || 0;
          const to = parseInt(pEl.getAttribute(toMonthly? 'data-month':'data-package'),10);
          animateNumber(span, from, to);
        });
      }
      switchEl.addEventListener('click',()=>{ monthly = !monthly; switchEl.classList.toggle('active',!monthly); switchEl.setAttribute('aria-checked', String(!monthly)); update(monthly); });
      switchEl.addEventListener('keydown',(e)=>{ if(e.key==='Enter' || e.key===' '){ e.preventDefault(); switchEl.click(); } });
      // initialize to monthly
      update(monthly);
    })();
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>How I Work — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#ffffff;--accent:#215b49;--muted:#52645b;--card:#fbfffc;--radius:14px;--maxw:920px}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, Arial;background:var(--bg);color:#122b23}
    header{padding:18px 20px;background:linear-gradient(180deg,#f6fbf9,transparent)}
    .nav{max-width:var(--maxw);margin:0 auto;display:flex;justify-content:space-between;align-items:center}
    .brand{font-weight:700;color:var(--accent)}
    nav a{color:var(--muted);text-decoration:none;margin-left:12px;padding:6px 8px;border-radius:8px}
    .container{max-width:var(--maxw);margin:26px auto;padding:0 18px}
    h1{margin:0 0 8px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:var(--card);padding:18px;border-radius:var(--radius);box-shadow:0 10px 30px rgba(17,33,27,0.04)}
    .pillars{display:flex;flex-direction:column;gap:12px}
    .pillar{display:flex;gap:12px;align-items:flex-start}
    .pill-title{font-weight:600;color:var(--accent)}
    .case-notes{margin-top:12px;font-size:14px;color:var(--muted)}

    /* small pricing comparator variant */
    .mini-toggle{display:flex;align-items:center;gap:8px;background:#fff;padding:6px;border-radius:999px;border:1px solid #edf7f0}
    .mini-switch{width:40px;height:22px;background:#f0fbf7;border-radius:999px;position:relative;cursor:pointer}
    .mini-knob{width:18px;height:18px;border-radius:50%;background:#fff;position:absolute;top:2px;left:2px;transition:left .22s}
    .mini-switch.active{background:var(--accent)}
    .mini-switch.active .mini-knob{left:20px}

    @media (max-width:920px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="nav">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Studio</a>
        <a href="specialties.html">Offerings</a>
        <a href="about.html">Who I Am</a>
        <a href="approach.html" class="active">How I Work</a>
        <a href="faq.html">Questions</a>
      </nav>
    </div>
  </header>

  <main class="container">
    <div class="grid">
      <section class="card">
        <h1>Clinical stance and structure</h1>
        <p class="case-notes">My work blends observation, collaborative formulation, and skill practice. I orient to what’s practical and what is emotionally manageable: small experiments that map onto your real life. Sessions are confidential; I will discuss limits to confidentiality, and I do not provide emergency care.</p>

        <div style="margin-top:14px" class="pillars">
          <div class="pillar">
            <div style="width:10px;height:40px;background:var(--accent);border-radius:6px"></div>
            <div>
              <div class="pill-title">Compassionate clarity</div>
              <div class="muted">We work toward clearer descriptions of what is occurring so your choices are informed rather than anxious. This is a collaborative process.</div>
            </div>
          </div>

          <div class="pillar">
            <div style="width:10px;height:40px;background:#77b99e;border-radius:6px"></div>
            <div>
              <div class="pill-title">Practical steps</div>
              <div class="muted">Short, doable tasks between sessions help turn insight into change. Plans are revisited and adjusted in session.</div>
            </div>
          </div>

          <div class="pillar">
            <div style="width:10px;height:40px;background:#cfeee0;border-radius:6px"></div>
            <div>
              <div class="pill-title">Ethical care</div>
              <div class="muted">Documentation, referrals, and collaboration are handled with care. You will be informed about record-keeping and limits to confidentiality.</div>
            </div>
          </div>
        </div>

        <section style="margin-top:14px">
          <h3 style="margin:0 0 8px">Clinical boundaries & crisis guidance</h3>
          <p class="muted">I do not respond to crisis matters via email or text. If you or someone is at immediate risk, contact emergency services. For non-urgent needs, please contact {{EMAIL}} or call {{PHONE}} to arrange an appointment.</p>
        </section>
      </section>

      <aside class="card">
        <h3 style="margin-top:0">Session rhythm</h3>
        <p class="muted">Many people benefit from consistent meetings over several months; others choose short packages to focus on a single issue. Below is a quick per-session comparison you can toggle.</p>

        <div style="margin-top:12px;display:flex;align-items:center;justify-content:space-between">
          <div class="mini-toggle" style="align-items:center">
            <div style="font-size:13px;color:var(--muted);margin-right:6px">Monthly</div>
            <div id="miniSwitch" class="mini-switch" role="switch" aria-checked="true" tabindex="0"><div class="mini-knob"></div></div>
            <div style="font-size:13px;color:var(--muted);margin-left:6px">Package</div>
          </div>
          <div style="text-align:right">
            <div style="font-size:13px;color:var(--muted)">Approx. per-session</div>
            <div style="font-size:20px;color:var(--accent);font-weight:600">$<span id="miniPrice">160</span></div>
          </div>
        </div>

        <div style="margin-top:12px"><a href="{{PRIMARY_CTA_URL}}" style="background:var(--accent);color:#fff;padding:10px 12px;border-radius:10px;text-decoration:none">Begin with a short conversation</a></div>

        <div style="margin-top:16px;font-size:13px;color:var(--muted)">
          Session length is typically 50 minutes. Options for longer or shorter sessions may be discussed at intake. Payment details and insurance use are addressed during scheduling.
        </div>
      </aside>
    </div>
  </main>

  <script>
    // Mini comparator with simple animation
    (function(){
      const sw = document.getElementById('miniSwitch');
      const priceEl = document.getElementById('miniPrice');
      let monthly = true;
      const values = {monthly:160, package:95}; // package shows lower per-session when bought as block
      function setPrice(toMonthly){
        const from = parseInt(priceEl.textContent,10) || 0;
        const to = toMonthly? values.monthly : values.package;
        const start = performance.now();
        const ms = 380;
        function step(now){
          const p = Math.min(1,(now-start)/ms);
          const val = Math.round(from + (to-from)*p);
          priceEl.textContent = val;
          if(p<1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }
      sw.addEventListener('click',()=>{ monthly = !monthly; sw.classList.toggle('active',!monthly); sw.setAttribute('aria-checked', String(!monthly)); setPrice(monthly); });
      sw.addEventListener('keydown',(e)=>{ if(e.key==='Enter' || e.key===' '){ e.preventDefault(); sw.click(); } });
      setPrice(monthly);
    })();
  </script>
</body>
</html>"} 
